<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('documents.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'documents');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='document'){$pdo->prepare('INSERT INTO documents(document_code,project_id,customer_id,category,title,file_name,file_path,mime_type,file_size,is_customer_visible,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([op_code('DOC'),fint('project_id'),fint('customer_id'),fpost('category','other'),fpost('title'),fpost('file_name')?:basename(fpost('file_path')?:'document'),fpost('file_path')?:'pending-upload',fpost('mime_type')?:null,fint('file_size'),fpost('visibility','staff')==='staff'?0:1,$staff['id']]);flash('success','Document record added.');}elseif($a==='note'){$pdo->prepare('INSERT INTO internal_notes(entity_type,entity_id,customer_id,project_id,note,is_pinned,created_by) VALUES(?,?,?,?,?,?,?)')->execute([fint('project_id')?'project':'customer',fint('project_id')?:fint('customer_id'),fint('customer_id'),fint('project_id'),fpost('note'),isset($_POST['pinned'])?1:0,$staff['id']]);flash('success','Internal note added.');}staff_redirect('staff/pages/documents.php');}
$projects=project_options($pdo);$customers=customer_options($pdo);$docs=db_rows($pdo,'SELECT d.*,p.project_code,c.name customer_name FROM documents d LEFT JOIN projects p ON p.id=d.project_id LEFT JOIN customers c ON c.id=d.customer_id ORDER BY d.created_at DESC');$notes=db_rows($pdo,'SELECT n.*,p.project_code,c.name customer_name,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) author FROM internal_notes n LEFT JOIN projects p ON p.id=n.project_id LEFT JOIN customers c ON c.id=n.customer_id LEFT JOIN staff s ON s.id=n.created_by ORDER BY n.is_pinned DESC,n.created_at DESC LIMIT 30');$pageTitle='Documents & Notes';require __DIR__.'/../../includes/staff/header.php';module_head('Records','Document Centre & Internal Notes','Centralise project files and staff-only context.');?>
<div class="split-grid"><section class="staff-panel"><h2>Add document record</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="document"><label>Title<input name="title" required></label><div class="two"><label>Project<select name="project_id"><option value="">None</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Customer<select name="customer_id"><option value="">None</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach?></select></label></div><div class="two"><label>Type<select name="category"><option>design</option><option>measurement</option><option>quotation</option><option>invoice</option><option>receipt</option><option>purchase_order</option><option>installation</option><option>warranty</option><option>other</option></select></label><label>Visibility<select name="visibility"><option>staff</option><option>customer</option><option>both</option></select></label></div><label>Stored file path<input name="file_path" placeholder="uploads/projects/..."></label><button class="btn primary">Save document</button></form></section><section class="staff-panel"><h2>Add internal note</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="note"><label>Project<select name="project_id"><option value="">None</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Customer<select name="customer_id"><option value="">None</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach?></select></label><label>Note<textarea name="note" required></textarea></label><label><input type="checkbox" name="pinned"> Pin note</label><button class="btn">Add note</button></form></section></div><section class="staff-panel"><h2>Pinned / recent notes</h2><?php foreach($notes as $n):?><div class="board-card"><b><?=h(($n['is_pinned']?'📌 ':'').($n['project_code']?:$n['customer_name']?:'General'))?></b><p><?=nl2br(h($n['note']))?></p><small><?=h($n['author']?:'Staff')?> · <?=h(date('j M Y g:i A',strtotime($n['created_at'])))?></small></div><?php endforeach?></section><section class="staff-panel table-panel"><h2>Documents</h2><table><thead><tr><th>Document</th><th>Project</th><th>Customer</th><th>Type</th><th>Visibility</th></tr></thead><tbody><?php foreach($docs as $d):?><tr><td><b><?=h($d['title'])?></b><small><?=h($d['document_code'])?></small></td><td><?=h($d['project_code']?:'—')?></td><td><?=h($d['customer_name']?:'—')?></td><td><?=h($d['category'])?></td><td><?=h($d['is_customer_visible']?'customer':'staff')?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>